from typing import List


def parse_music(music_string: str) -> List[int]:
    notes = {
        'o': [4],
        'o|': [2],
        '.|': [1]
    }

    result = []
    current_note = ''

    for char in music_string:
        if char == ' ' or (char != '|' and not current_note):
            if current_note:
                result.extend(notes[current_note])
                current_note = ''

        elif char == '|':
            if current_note:
                notes[current_note].append(0)
                current_note += '|'

        else:
            current_note += char

    return [int(i) for sublist in [notes[note] for note in music_string.split()] for i in sublist]

def sort_numbers(numbers: str) -> str:
    num_dict = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
                'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    numbers_list = [num_dict[num] for num in numbers.split()]
    sorted_numbers = sorted(numbers_list)
    return ' '.join([str(num) for num in sorted_numbers])
